#!/usr/bin/env bash\n\n# nightly-apt-cleanup-helper\n# Scan for packages that would be removed by `apt-get autoremove` and optionally purge them.\n# Whimsical post‑apocalyptic messaging included.\n\nset -euo pipefail\n\n# Colors for fun (fallback to no‑color if not a tty)\nif [[ -t 1 ]]; then\n  RED='\e[31m'\n  GREEN='\e[32m'\n  YELLOW='\e[33m'\n  BLUE='\e[34m'\n  RESET='\e[0m'\nelse\n  RED='' GREEN='' YELLOW='' BLUE='' RESET=''\nfi\n\nprint_msg() {\n  local type="$1"; shift\n  case "$type" in\n    info)   echo -e "${BLUE}[⚙️]${RESET} $*" ;;\n    list)   echo -e "${YELLOW}[📦]${RESET} $*" ;;\n    prompt) echo -e "${GREEN}[❓]${RESET} $*" ;;\n    success) echo -e "${GREEN}[✅]${RESET} $*" ;;\n    error)   echo -e "${RED}[❌]${RESET} $*" >&2 ;;\n    *)       echo "$*" ;;\n  esac\n}\n\n# Determine if we are in test mode (presence of MOCK_APT env var)\nif [[ "${MOCK_APT:-}" == "1" ]]; then\n  # In test mode we rely on a mock `apt-get` placed earlier in $PATH\n  :\nfi\n\n# Parse arguments\nAUTO_CONFIRM=false\nwhile getopts ":y" opt; do\n  case $opt in\n    y) AUTO_CONFIRM=true ;;\n    \?) print_msg error "Invalid option: -$OPTARG"; exit 1 ;;\n  esac\ndone\nshift $((OPTIND -1))\n\n# Function to get list of packages that would be removed\nget_autoremove_list() {\n  # Use apt-get -s autoremove for a simulation.\n  # The output lines we care about look like: "  The following packages will be REMOVED:"\n  # followed by a line with package names.\n  local output\n  output=$(apt-get -s autoremove 2>/dev/null || true)\n  # Extract package names after the "REMOVED:" line\n  local packages\n  packages=$(echo "$output" | awk '/The following packages will be REMOVED:/ {getline; print}' | tr -d '\n')\n  echo "$packages"\n}\n\nprint_msg info "Scavenging the wasteland for abandoned packages..."\nPKGS=$(get_autoremove_list)\n\nif [[ -z "$PKGS" ]]; then\n  print_msg success "No debris found. The wasteland is already clean!"\n  exit 0\nfi\n\nprint_msg list "Packages to be removed: $PKGS"\n\nif $AUTO_CONFIRM; then\n  PROCEED=yes\nelse\n  print_msg prompt "Proceed with removal? (y/N) "\n  read -r PROCEED\nfi\n\nif [[ "$PROCEED" =~ ^[Yy]$ ]]; then\n  print_msg info "Initiating purge..."\n  # Perform actual removal. Use sudo if not root.\n  if [[ $(id -u) -ne 0 ]]; then\n    SUDO="sudo"\n  else\n    SUDO=""\n  fi\n  $SUDO apt-get -y autoremove > /dev/null\n  # Simulate per‑package messages (since apt-get already does the work)\n  for pkg in $PKGS; do\n    echo "Removing $pkg... Done."\n  done\n  print_msg success "Debris cleared!"\nelse\n  print_msg info "Aborted. The wasteland remains untouched."\nfi\n
